    /// bool : if true, the order will only be posted to the order book and not executed immediately, default is false
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.timeInForce</term>
    /// <description>
    /// string : 'GTC', 'IOC' or 'FOK'
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.cost</term>
    /// <description>
    /// float : *market buy and trailing buy orders only* the quote quantity that can be used as an alternative for the amount
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.triggerPrice</term>
    /// <description>
    /// float : the price that a trigger order is triggered at, same as takeProfitPrice
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.stopLossPrice</term>
    /// <description>
    /// float : the price that a stop loss order is triggered at
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.takeProfitPrice</term>
    /// <description>
    /// float : the price that a take profit order is triggered at
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.triggerPriceType</term>
    /// <description>
    /// string : 'last', 'mark' or 'index', default is 'last'
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.trailingAmount</term>
    /// <description>
    /// float : the quote amount to trail away from the current market price
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.trailingPercent</term>
    /// <description>
    /// float : the percent to trail away from the current market price
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.deviation</term>
    /// <description>
    /// float : *PEG orders only* how much should the order price deviate from the pegged price, in percent from -10 to 10
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.stealth</term>
    /// <description>
    /// float : *PEG orders only* how many percent of the order is to be displayed on the orderbook, from 1 to 100
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.stopPrice</term>
    /// <description>
    /// float : *NB - It is NOT stopLossPrice or triggerPrice!!! OCO orders only* the limit price of the stop loss leg
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object</term> an [order structure]{@link https://docs.ccxt.com/?id=order-structure}.</returns>
    public async Task<Order> CreateSpotOrder(string symbol, string type, string side, double amount, double? price = null, Dictionary<string, object> parameters = null)
    {
        var res = await this.createSpotOrder(symbol, type, side, amount, price, parameters);
        return new Order(res);
    }
    /// <summary>
