    public async Task<List<Position>> FetchPositionsForSymbol(string symbol, Dictionary<string, object> parameters = null)
    {
        var res = await this.fetchPositionsForSymbol(symbol, parameters);
        return ((IList<object>)res).Select(item => new Position(item)).ToList<Position>();
    }
    /// <summary>
    /// fetchs the position mode, hedged or one way, hedged for btse is set identically for all linear markets or all inverse markets
    /// </summary>
    /// <remarks>
    /// See <see href="https://docs.btse.com/futures/rest/get-position-mode"/>  <br/>
    /// <list type="table">
    /// <item>
    /// <term>params</term>
    /// <description>
    /// object : extra parameters specific to the exchange API endpoint
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object</term> an object detailing whether the market is in hedged or one-way mode.</returns>
    public async Task<ccxt.PositionModeInfo> FetchPositionMode(string symbol = null, Dictionary<string, object> parameters = null)
    {
        var res = await this.fetchPositionMode(symbol, parameters);
        return res;
    }
    /// <summary>
    /// NB!!! This method also sets margin mode to cross on btse. Set hedged to true or false for a cross-margin market.
    /// </summary>
    /// <remarks>
    /// See <see href="https://docs.btse.com/futures/rest/change-position-mode"/>  <br/>
    /// <list type="table">
    /// <item>
